<head>
    <meta charset="UTF-8">
    <title>Pendulum Simulation</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="canvas" width="500" height="500"></canvas>
    <form>
        <label for="angle">Initial Angle:</label><br>
        <input type="number" id="angle" value="45"><br>
        <button id="start">Release Pendulum</button>
    </form>
    <script>
        let canvas = document.getElementById('canvas');
        let ctx = canvas.getContext('2d');
        let pendulum = {};
        let angle = 0;
        let angularVelocity = 0;
        let g = 0.098; // m/s^2, assuming 10% of the acceleration due to gravity

        ctx.translate(canvas.width / 2, canvas.height / 2);

        document.getElementById('start').addEventListener('click', startPendulum);

        function startPendulum() {
            angle = parseInt(document.getElementById('angle').value);
            angularVelocity = 0;
            pendulum.angle = angle * Math.PI / 180;
            pendulum.angularVelocity = 0;
            animate();
        }

        function animate() {
            update();
            render();
            requestAnimationFrame(animate);
        }

        function update() {
            let torque = -g * pendulum.length * Math.sin(pendulum.angle);
            pendulum.angularAcceleration = torque / pendulum.length;
            pendulum.angularVelocity += pendulum.angularAcceleration;
            pendulum.angle += pendulum.angularVelocity;
        }

        function render() {
            ctx.clearRect(-250, -250, 500, 500);

            let pendulumX = pendulum.length * Math.sin(pendulum.angle);
            let pendulumY = -pendulum.length * Math.cos(pendulum.angle);

            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(pendulumX, pendulumY);
            ctx.stroke();

            ctx.beginPath();
            ctx.arc(0, 0, 5, 0, 2 * Math.PI);
            ctx.fill();

            ctx.beginPath();
            ctx.arc(pendulumX, pendulumY, 5, 0, 2 * Math.PI);
            ctx.fill();
        }

        pendulum.length = 200; // in pixels
    </script>
</body>
</html>
```

